    33	    public String generateOccupancyReport(LocalDate date) {
    34	        StringBuilder csv = new StringBuilder();
    35	
    36	        csv.append(POUSADA_NAME).append(",occupancy,").append(formatDate(date)).append("\n");
    37	        csv.append("room,type,reservation,check_in,check_out\n");
    38	
    39	        Map<Integer, Room> allRooms = roomRepo.findAll();
    40	        List<Integer> roomNumbers = new ArrayList<>(allRooms.keySet());
    41	        Collections.sort(roomNumbers);
