    43	        int occupiedCount = 0;
    44	        for (int roomNumber : roomNumbers) {
    45	            Room room = allRooms.get(roomNumber);
    46	            boolean occupied = false;
    47	
    48	            for (Reservation res : reservationRepo.findAll().values()) {
    49	                if (res.getRoomNumber() == roomNumber && res.getStatus() != ReservationStatus.CANCELLED) {
