 41	package com.pousada.service;
 42	
 43	import com.pousada.domain.RatePlan;
 44	import java.math.BigDecimal;
 45	import java.math.RoundingMode;
 46	import java.time.LocalDate;
 47	
 48	public class PricingService {
 49	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 50	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
 51	
 52	    public BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
 53	        if (isHighSeason(date)) {
 54	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
 55	        }
 56	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
 57	    }
 58	
 59	    public PricingResult calculatePrice(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut,
 60	                                       RatePlan ratePlan) {
 61	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 62	        BigDecimal subtotal = BigDecimal.ZERO;
 63	
 64	        LocalDate currentDate = checkIn;
 65	        while (currentDate.isBefore(checkOut)) {
 66	            BigDecimal nightlyRate = calculateNightlyRate(baseRate, currentDate);
 67	            subtotal = subtotal.add(nightlyRate);
 68	            currentDate = currentDate.plusDays(1);
 69	        }
 70	
 71	        subtotal = subtotal.setScale(2, RoundingMode.HALF_EVEN);
 72	
 73	        BigDecimal discount = BigDecimal.ZERO;
