 85	        int day = date.getDayOfMonth();
 86	
 87	        if (month == 7) {
 88	            return true;
 89	        }
 90	
 91	        if (month == 12) {
 92	            return day >= 15;
 93	        }
 94	
 95	        if (month == 1 || month == 2) {
 96	            return true;
 97	        }
 98	
 99	        return false;
100	    }
101	
